// materialWorktreeClean reports whether the working copy equals HEAD in every
// path outside the administrative classes, untracked files included. A status
// that cannot be read is not clean.
func materialWorktreeClean(root string) bool {
	// Mode changes count whatever core.fileMode says (review round 13, N36).
	out, err := gitOutputBounded(root, 16*1024*1024, "-c", "core.fileMode=true", "status", "--porcelain=v1", "-z", "--ignore-submodules=none", "--untracked-files=all")
	if err != nil {
		return false
	}
	records := strings.Split(string(out), "\x00")
	var administrative []string
	for i := 0; i < len(records); i++ {
		record := records[i]
		if len(record) < 4 {
			continue
		}
		paths := []string{record[3:]}
		if record[0] == 'R' || record[0] == 'C' || record[1] == 'R' || record[1] == 'C' {
			// A rename or copy carries its source as the next record.
			if i+1 < len(records) {
				i++
				paths = append(paths, records[i])
			}
		}
		for _, p := range paths {
			if !posemodel.IsAdministrativePath(p) {
				return false
			}
			administrative = append(administrative, p)
		}
	}
	return administrativeRecordsAreRegular(root, administrative)
}

